import type { TripInsert } from '@/services/tripService';
import type { TripItineraryInsert, ActivityInsert } from '@/services/itineraryService';

// ============ AI 生成的行程方案类型 ============

export interface PlanActivity {
  time: string;
  name: string;
  description: string;
